import {newMaterialLayer} from './material-runtime.js';
import {icon} from './icons.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const select=(files,kind,value)=>'<option value="">없음</option>'+[...files.filter(f=>f.kind===kind),...(value&&!files.some(f=>f.path===value)?[{path:value,name:value}]:[])].map(f=>`<option value="${esc(f.path)}" ${f.path===value?'selected':''}>${esc(f.name)}</option>`).join('');
export function materialLayersFields(layers,files,parameters=[]){
  return `<div class="material-layer-stack">${layers.map((layer,index)=>`<details class="material-layer-entry" data-layer-id="${layer.id}" open><summary>${icon('layers')}<strong>${esc(layer.name||'Layer '+index)}</strong><small>${index===0?'배경':index}</small></summary><div class="material-layer-actions">${index?`<label><input type="checkbox" data-layer-field="enabled" ${layer.enabled?'checked':''}>표시</label><button data-layer-action="up" ${index===1?'disabled':''} title="위로" aria-label="레이어 위로">${icon('arrowUp')}</button><button data-layer-action="down" ${index===layers.length-1?'disabled':''} title="아래로" aria-label="레이어 아래로">${icon('arrowDown')}</button><button data-layer-action="remove" title="삭제" aria-label="레이어 삭제">${icon('close')}</button>`:''}<button data-layer-action="duplicate" title="복제" aria-label="레이어 복제">${icon('copy')}</button></div><label class="material-node-field"><span>이름</span><input data-layer-field="name" value="${esc(layer.name)}"></label><label class="material-node-field"><span>레이어</span><select data-layer-field="asset">${select(files,'materiallayer',layer.asset)}</select></label><button data-layer-open="${esc(layer.asset)}">레이어 열기</button>${index?`<label class="material-node-field"><span>블렌드</span><select data-layer-field="blend">${select(files,'materialblend',layer.blend)}</select></label>${layer.blend?`<button data-layer-open="${esc(layer.blend)}">블렌드 열기</button>`:''}`:''}${['layer','blend'].map(domain=>{const values=domain==='layer'?layer.parameters:layer.blendParameters;return parameters.filter(p=>p.scope?.id===layer.id&&p.scope.domain===domain).map(p=>{const name=p.label,enabled=Object.hasOwn(values,name),value=enabled?values[name]:p.value,attrs=`data-layer-param="${esc(name)}" data-layer-domain="${domain}"`;return `<div class="material-layer-parameter"><label><input type="checkbox" data-layer-override="${esc(name)}" data-layer-domain="${domain}" ${enabled?'checked':''}>${esc(name)}${domain==='blend'?' · 블렌드':''}</label>${p.type==='vec3'?`<div class="asset-vector-fields">${value.map((v,i)=>`<input type="number" step=".05" value="${v}" ${attrs} data-axis="${i}" aria-label="${esc(name)} ${'XYZ'[i]}">`).join('')}</div>`:p.type==='texture'?`<select ${attrs}>${select(files,'texture',value)}</select>`:p.type==='bool'?`<input type="checkbox" ${value?'checked':''} ${attrs} aria-label="${esc(name)} 값">`:`<input type="number" step=".01" value="${value}" ${attrs} aria-label="${esc(name)} 값">`}</div>`;}).join('');}).join('')}</details>`).join('')}<div class="material-layer-add"><select data-new-layer aria-label="추가할 머테리얼 레이어">${select(files,'materiallayer','')}</select><button data-layer-action="add" aria-label="레이어 추가">${icon('plus')} 추가</button></div></div>`;
}
export function editMaterialLayers(layers,target,parameters=[]){
  const entry=target.closest('[data-layer-id]'),index=layers.findIndex(l=>l.id===entry?.dataset.layerId),layer=layers[index],action=target.dataset.layerAction;
  if(action==='add'){const select=target.closest('.material-layer-stack').querySelector('[data-new-layer]');if(!select.value)return false;layers.push(newMaterialLayer(select.value,select.selectedOptions[0].textContent));return true;}
  if(!layer)return false;
  if(action){if(action==='duplicate'){const next=structuredClone(layer);next.id=newMaterialLayer(layer.asset,layer.name).id;next.name=(layer.name+' 복사').slice(0,80);layers.splice(index+1,0,next);}else if(action==='remove'&&index)layers.splice(index,1);else if(['up','down'].includes(action)){const to=index+(action==='up'?-1:1);if(!index||to<1||to>=layers.length)return false;[layers[index],layers[to]]=[layers[to],layers[index]];}else return false;return true;}
  if(target.dataset.layerField){const field=target.dataset.layerField;if(!['name','asset','blend','enabled'].includes(field)||index===0&&['blend','enabled'].includes(field))return false;layer[field]=target.type==='checkbox'?target.checked:target.value;if(field==='asset')layer.parameters={};if(field==='blend')layer.blendParameters={};return true;}
  const name=target.dataset.layerOverride||target.dataset.layerParam,domain=target.dataset.layerDomain;if(!name||!['layer','blend'].includes(domain))return false;const values=domain==='layer'?layer.parameters:layer.blendParameters,descriptor=parameters.find(p=>p.scope?.id===layer.id&&p.scope.domain===domain&&p.label===name);if(!descriptor)return false;
  if(target.dataset.layerOverride){if(target.checked)values[name]=structuredClone(descriptor.value);else delete values[name];}
  else if(target.dataset.axis!==undefined){values[name]=structuredClone(values[name]??descriptor.value);values[name][Number(target.dataset.axis)]=Number(target.value);}else values[name]=target.type==='checkbox'?target.checked:target.type==='number'?Number(target.value):target.value;return true;
}
